    for board, cnt in get_board_distribution().items():
        print(f"  {board:10s}: {cnt}")

    print("\n=== 标的列表（前 20）===")
    for sym in universe[:20]:
        print(f"  {sym}")
    print(f"  ... 共 {len(universe)} 个标的")